return ['domain'=>'bulk-editor','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'uk','project-id-version'=>'WOLF - WordPress Posts Bulk Editor and Manager Professional 2.1.3','pot-creation-date'=>'2026-11-20T14:15:27+00:00','po-revision-date'=>'2026-11-20 15:00+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['WOLF - WordPress Posts Bulk Editor and Manager Professional'=>'WOLF - WordPress Posts Bulk Editor and Manager Professional','https://bulk-editor.pro/'=>'https://bulk-editor.pro/','Tools for managing and bulk edit posts, pages and all custom types data in the reliable and flexible way! Be professionals with managing data of your site!'=>'Інструменти для керування та масового редагування записів, сторінок і даних усіх власних типів записів надійно та гнучко! Керуйте даними свого сайту як професіонал!','realmag777'=>'realmag777','https://pluginus.net/'=>'https://pluginus.net/','no rounding'=>'без округлення','forbidden'=>'заборонено','Default'=>'Типово','Checkboxes for the posts selection. Use SHIFT button on your keyboard to select multiple rows.'=>'Прапорці для вибору записів. Утримуйте клавішу SHIFT, щоб вибрати кілька рядків.','Thumbnail'=>'Мініатюра','Title'=>'Заголовок','Content'=>'Вміст','Excerpt'=>'Уривок','Slug'=>'Слаг','Status'=>'Статус','Comment status'=>'Статус коментування','Can users comment post or not.'=>'Чи можуть користувачі коментувати запис.','Open'=>'Відкрито','Closed'=>'Закрито','Ping status'=>'Статус пінгів','A ping is a [this site has new content] notification that invites search engine bots to visit your blog.'=>'Пінг - це сповіщення «на сайті новий вміст», яке запрошує пошукових ботів відвідати ваш блог.','Send trackbacks to'=>'Надсилати трекбеки на','Separate multiple URLs with spaces. Ping status should be open! Remove 2 links separated by space, save. After opening you will not see links as they had been pinged! No sense for roll back, its sending is instant. Trackbacks are a way to notify legacy blog systems that you’ve linked to them. If you link other WordPress sites, they’ll be notified automatically using pingbacks, no other action necessary. Do not use these fields for something else. They are parsed many times in core code (69 matches for to_ping); their format is fixed.'=>'Розділяйте кілька URL пробілами. Статус пінгів має бути відкритим! Видаліть 2 посилання, розділені пробілом, і збережіть. Після відкриття ви не побачите посилань, бо їх уже пінгували! Відкат не має сенсу, надсилання відбувається миттєво. Трекбеки - це спосіб сповістити старі блогові системи, що ви на них послалися. Якщо ви посилаєтеся на інші сайти WordPress, вони отримають сповіщення автоматично через пінгбеки, жодних додаткових дій не потрібно. Не використовуйте ці поля для іншого. Вони багато разів обробляються в ядрі (69 збігів для to_ping); їхній формат фіксований.','Post password'=>'Пароль запису','Password for private posts'=>'Пароль для приватних записів','Menu order'=>'Порядок у меню','Custom ordering position.'=>'Власна позиція в порядку сортування.','Author'=>'Автор','Date Published'=>'Дата публікації','Date Published GMT'=>'Дата публікації GMT','Date modified'=>'Дата зміни','Date modified GMT'=>'Дата зміни GMT','Post parent'=>'Батьківський запис','Post type'=>'Тип запису','Post mime type'=>'MIME-тип запису','Not in bulk edit as there is no built-uploader here, so no sense change mime type. Filtering only! The function is designed specifically for attached records.'=>'Немає в масовому редагуванні, бо тут немає вбудованого завантажувача, тож змінювати MIME-тип немає сенсу. Лише фільтрування! Функція призначена саме для прикріплених записів.','Sticky'=>'Закріплений','Stick this post to the front page'=>'Закріпити цей запис на головній сторінці','Yes'=>'Так','No'=>'Ні','Default posts count per page'=>'Типова кількість записів на сторінці','How many rows shows per page in tab Posts Editor. Max possible value is 100!'=>'Скільки 